// Gerado automaticamente. Edite os arquivos na raiz, não este arquivo.
const FILES = {"/index.html":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"theme-color\" content=\"#174CA0\">\n  <meta name=\"description\" content=\"Calcule tamanho da amostra e intervalos de confiança, com explicações simples e claras.\">\n  <title>Estatística Aplicada — Calculadora</title>\n  <link rel=\"stylesheet\" href=\"./assets/style.css\">\n  <script src=\"./src/calculos.js\" defer></script>\n  <script src=\"./src/app.js\" defer></script>\n</head>\n<body>\n  <header class=\"cabecalho\">\n    <div class=\"largura topo\">\n      <a class=\"marca\" href=\"./\" aria-label=\"Estatística Aplicada — início\">\n        <span class=\"marca-sinal\" aria-hidden=\"true\">Σ</span>\n        <span>Estatística <strong>Aplicada</strong></span>\n      </a>\n      <span class=\"marca-extra\">Calculadora da disciplina</span>\n    </div>\n  </header>\n\n  <main class=\"largura\">\n    <div class=\"introducao\">\n      <span class=\"sobretitulo\">FÓRMULAS DA AULA</span>\n      <h1>Qual cálculo você precisa fazer?</h1>\n      <p>Escolha o assunto, preencha os valores do exercício e veja como chegar à resposta.</p>\n    </div>\n\n    <!-- As cinco abas são os cinco assuntos do index.html de referência. -->\n    <nav class=\"abas\" aria-label=\"Escolher cálculo\">\n      <button type=\"button\" class=\"aba ativa\" data-aba=\"am\" aria-current=\"page\"><small>Tamanho da amostra</small><strong>Média</strong></button>\n      <button type=\"button\" class=\"aba\" data-aba=\"ap\"><small>Tamanho da amostra</small><strong>Proporção</strong></button>\n      <button type=\"button\" class=\"aba\" data-aba=\"im\"><small>Intervalo de confiança</small><strong>Média</strong></button>\n      <button type=\"button\" class=\"aba\" data-aba=\"ip\"><small>Intervalo de confiança</small><strong>Proporção</strong></button>\n      <button type=\"button\" class=\"aba\" data-aba=\"de\"><small>Ajuste da amostra</small><strong>Diminuir o erro</strong></button>\n    </nav>\n\n    <!-- Assunto 1: calcular quantas observações são necessárias para a média. -->\n    <section class=\"assunto visivel\" id=\"aba-am\" aria-labelledby=\"titulo-am\">\n      <h2 id=\"titulo-am\">Tamanho da amostra para a média</h2>\n      <p class=\"descricao\">Quantas observações preciso para estimar uma média com a precisão desejada?</p>\n      <div class=\"colunas\">\n        <form class=\"cartao dados\" id=\"form-am\" novalidate>\n          <h3>Dados do exercício</h3>\n          <label for=\"am-confianca\">Grau de confiança</label>\n          <div class=\"confianca\"><select id=\"am-confianca\" name=\"confianca\"><option value=\"90\">90%</option><option value=\"95\" selected>95%</option><option value=\"99\">99%</option></select><output data-z=\"am\">Z = 1,96</output></div>\n          <label for=\"am-desvio\">Desvio-padrão populacional (σ)</label>\n          <input id=\"am-desvio\" name=\"desvio\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite o desvio-padrão\">\n          <label for=\"am-erro\">Erro amostral máximo aceito (Em)</label>\n          <input id=\"am-erro\" name=\"erro\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite a margem de erro\">\n          <div class=\"erro\" role=\"alert\" hidden></div>\n          <div class=\"acoes\"><button class=\"primario\" type=\"submit\">Calcular</button><button class=\"limpar\" type=\"reset\">Limpar</button></div>\n        </form>\n        <aside class=\"cartao formula\"><h3>Fórmula utilizada</h3><div class=\"expressao\">n = (Z · σ / Em)²</div><dl><dt>n</dt><dd>Tamanho mínimo da amostra</dd><dt>σ</dt><dd>Desvio-padrão populacional</dd><dt>Em</dt><dd>Erro máximo aceito</dd><dt>Z</dt><dd>Valor relacionado à confiança</dd></dl></aside>\n      </div>\n      <div class=\"resultado\" hidden></div>\n    </section>\n\n    <!-- Assunto 2: amostra necessária para estimar uma porcentagem. -->\n    <section class=\"assunto\" id=\"aba-ap\" aria-labelledby=\"titulo-ap\" hidden>\n      <h2 id=\"titulo-ap\">Tamanho da amostra para a proporção</h2>\n      <p class=\"descricao\">Quantas pessoas ou observações preciso para estimar uma porcentagem?</p>\n      <div class=\"colunas\">\n        <form class=\"cartao dados\" id=\"form-ap\" novalidate>\n          <h3>Dados do exercício</h3>\n          <label for=\"ap-confianca\">Grau de confiança</label>\n          <div class=\"confianca\"><select id=\"ap-confianca\" name=\"confianca\"><option value=\"90\">90%</option><option value=\"95\" selected>95%</option><option value=\"99\">99%</option></select><output data-z=\"ap\">Z = 1,96</output></div>\n          <label for=\"ap-p\">Proporção estimada (p), em %</label>\n          <input id=\"ap-p\" name=\"p\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite a porcentagem\">\n          <label class=\"marcar\"><input type=\"checkbox\" name=\"desconhecida\" id=\"ap-desconhecida\"> Proporção desconhecida (usar 50%)</label>\n          <div class=\"dado-automatico\"><span>Complemento (1 − p)</span><output id=\"ap-complemento\">—</output></div>\n          <label for=\"ap-erro\">Erro da proporção (Ep), em %</label>\n          <input id=\"ap-erro\" name=\"erro\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite o erro em %\">\n          <div class=\"erro\" role=\"alert\" hidden></div>\n          <div class=\"acoes\"><button class=\"primario\" type=\"submit\">Calcular</button><button class=\"limpar\" type=\"reset\">Limpar</button></div>\n        </form>\n        <aside class=\"cartao formula\"><h3>Fórmula utilizada</h3><div class=\"expressao\">n = Z² · p · (1 − p) / Ep²</div><dl><dt>p</dt><dd>Proporção estimada</dd><dt>1 − p</dt><dd>Complemento da proporção</dd><dt>Ep</dt><dd>Erro da proporção, em decimal</dd><dt>Z</dt><dd>Valor relacionado à confiança</dd></dl></aside>\n      </div>\n      <div class=\"resultado\" hidden></div>\n    </section>\n\n    <!-- Assunto 3: intervalo entre dois valores para a média. -->\n    <section class=\"assunto\" id=\"aba-im\" aria-labelledby=\"titulo-im\" hidden>\n      <h2 id=\"titulo-im\">Intervalo de confiança para a média</h2>\n      <p class=\"descricao\">Entre quais valores pode estar a média verdadeira da população?</p>\n      <div class=\"colunas\">\n        <form class=\"cartao dados\" id=\"form-im\" novalidate>\n          <h3>Dados do exercício</h3>\n          <label for=\"im-confianca\">Grau de confiança</label>\n          <div class=\"confianca\"><select id=\"im-confianca\" name=\"confianca\"><option value=\"90\">90%</option><option value=\"95\" selected>95%</option><option value=\"99\">99%</option></select><output data-z=\"im\">Z = 1,96</output></div>\n          <label for=\"im-media\">Média amostral (x̄)</label><input id=\"im-media\" name=\"media\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite a média\">\n          <label for=\"im-desvio\">Desvio-padrão (σ ou s)</label><input id=\"im-desvio\" name=\"desvio\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite o desvio-padrão\">\n          <label for=\"im-n\">Tamanho da amostra (n)</label><input id=\"im-n\" name=\"n\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"Digite a quantidade\">\n          <div class=\"erro\" role=\"alert\" hidden></div>\n          <div class=\"acoes\"><button class=\"primario\" type=\"submit\">Calcular</button><button class=\"limpar\" type=\"reset\">Limpar</button></div>\n        </form>\n        <aside class=\"cartao formula\"><h3>Fórmulas utilizadas</h3><div class=\"expressao\">Em = Z · σ / √n</div><div class=\"expressao\">IC = x̄ ± Em</div><dl><dt>x̄</dt><dd>Média da amostra</dd><dt>Em</dt><dd>Margem de erro calculada</dd><dt>n</dt><dd>Quantidade de observações</dd></dl></aside>\n      </div>\n      <div class=\"resultado\" hidden></div>\n    </section>\n\n    <!-- Assunto 4: intervalo entre duas porcentagens. -->\n    <section class=\"assunto\" id=\"aba-ip\" aria-labelledby=\"titulo-ip\" hidden>\n      <h2 id=\"titulo-ip\">Intervalo de confiança para a proporção</h2>\n      <p class=\"descricao\">Entre quais porcentagens pode estar a proporção verdadeira da população?</p>\n      <div class=\"colunas\">\n        <form class=\"cartao dados\" id=\"form-ip\" novalidate>\n          <h3>Dados do exercício</h3>\n          <label for=\"ip-confianca\">Grau de confiança</label>\n          <div class=\"confianca\"><select id=\"ip-confianca\" name=\"confianca\"><option value=\"90\">90%</option><option value=\"95\" selected>95%</option><option value=\"99\">99%</option></select><output data-z=\"ip\">Z = 1,96</output></div>\n          <label for=\"ip-sucessos\">Quantidade com a característica</label><input id=\"ip-sucessos\" name=\"sucessos\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"Digite a quantidade\">\n          <label for=\"ip-n\">Tamanho da amostra (n)</label><input id=\"ip-n\" name=\"n\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"Digite o total pesquisado\">\n          <div class=\"dado-automatico\"><span>Proporção da amostra</span><output id=\"ip-proporcao\">—</output></div>\n          <label for=\"ip-padrao\">Padrão aceitável (%) <span class=\"opcional\">— opcional</span></label><input id=\"ip-padrao\" name=\"padrao\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Somente se o exercício pedir\">\n          <div class=\"erro\" role=\"alert\" hidden></div>\n          <div class=\"acoes\"><button class=\"primario\" type=\"submit\">Calcular</button><button class=\"limpar\" type=\"reset\">Limpar</button></div>\n        </form>\n        <aside class=\"cartao formula\"><h3>Fórmulas utilizadas</h3><div class=\"expressao\">p = sucessos / n</div><div class=\"expressao\">Ep = Z · √[p(1 − p) / n]</div><div class=\"expressao\">IC = p ± Ep</div><dl><dt>p</dt><dd>Proporção da amostra</dd><dt>Ep</dt><dd>Margem de erro da proporção</dd><dt>n</dt><dd>Total pesquisado</dd></dl></aside>\n      </div>\n      <div class=\"resultado\" hidden></div>\n    </section>\n\n    <!-- Assunto 5: a amostra cresce quando exigimos erro menor. -->\n    <section class=\"assunto\" id=\"aba-de\" aria-labelledby=\"titulo-de\" hidden>\n      <h2 id=\"titulo-de\">Diminuir o erro da média</h2>\n      <p class=\"descricao\">Se eu quiser um erro menor, quantas observações adicionais serão necessárias?</p>\n      <div class=\"colunas\">\n        <form class=\"cartao dados\" id=\"form-de\" novalidate>\n          <h3>Dados do exercício</h3>\n          <label for=\"de-confianca\">Grau de confiança</label>\n          <div class=\"confianca\"><select id=\"de-confianca\" name=\"confianca\"><option value=\"90\">90%</option><option value=\"95\" selected>95%</option><option value=\"99\">99%</option></select><output data-z=\"de\">Z = 1,96</output></div>\n          <label for=\"de-desvio\">Desvio-padrão (σ ou s)</label><input id=\"de-desvio\" name=\"desvio\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite o desvio-padrão\">\n          <label for=\"de-n\">Tamanho atual da amostra (n)</label><input id=\"de-n\" name=\"n\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"Digite o tamanho atual\">\n          <div class=\"dado-automatico\"><span>Erro atual (Em)</span><output id=\"de-atual\">—</output></div>\n          <label for=\"de-k\">Dividir o erro por quantas vezes?</label><input id=\"de-k\" name=\"k\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite um valor maior que 1\">\n          <div class=\"erro\" role=\"alert\" hidden></div>\n          <div class=\"acoes\"><button class=\"primario\" type=\"submit\">Calcular</button><button class=\"limpar\" type=\"reset\">Limpar</button></div>\n        </form>\n        <aside class=\"cartao formula\"><h3>Fórmulas utilizadas</h3><div class=\"expressao\">Novo Em = Em / k</div><div class=\"expressao\">Novo n = (Z · σ / Novo Em)²</div><dl><dt>k</dt><dd>Quantas vezes o erro vai diminuir</dd><dt>Em</dt><dd>Margem de erro atual</dd><dt>n</dt><dd>Quantidade de observações</dd></dl><p class=\"nota-formula\">Ao reduzir o erro pela metade, precisamos de aproximadamente 4 vezes mais observações.</p></aside>\n      </div>\n      <div class=\"resultado\" hidden></div>\n    </section>\n\n    <footer class=\"rodape\"><span>Uma ferramenta de apoio aos exercícios de Estatística Aplicada.</span><span>RFB · 2026</span></footer>\n  </main>\n</body>\n</html>\n","/assets/style.css":"/*\n * VISUAL — modifique cores e espaços aqui, sem mexer nas fórmulas.\n * Apenas azul, tons neutros e branco. Não usamos bibliotecas de estilo.\n */\n:root { color-scheme: light; --azul:#2157af; --azul-forte:#153f85; --azul-claro:#edf3fd;\n  --texto:#192638; --secundario:#617188; --linha:#dbe3ef; --fundo:#f7f9fc; --branco:#fff; }\n* { box-sizing:border-box; }\nbody { margin:0; font:15px/1.55 system-ui,-apple-system,\"Segoe UI\",Arial,sans-serif; background:var(--fundo); color:var(--texto); }\nbutton, input, select { font:inherit; }\nbutton { cursor:pointer; }\n[hidden] { display:none !important; }\n.largura { width:min(1130px,calc(100% - 44px)); margin-inline:auto; }\n.cabecalho { background:#fff; border-bottom:1px solid var(--linha); }\n.topo { min-height:73px; display:flex; justify-content:space-between; align-items:center; gap:20px; }\n.marca { display:inline-flex; align-items:center; gap:11px; color:var(--texto); text-decoration:none; font-size:19px; letter-spacing:-.55px; }\n.marca strong { color:var(--azul); font-weight:700; }\n.marca-sinal { display:grid; place-items:center; background:var(--azul-forte); color:white; width:37px; height:37px; border-radius:9px; font-size:22px; font-weight:650; }\n.marca-extra { color:var(--secundario); font-size:13px; }\n.introducao { padding:40px 0 23px; }\n.sobretitulo { font-size:11px; font-weight:800; letter-spacing:1.5px; color:var(--azul); }\nh1 { font-size:clamp(27px,3.8vw,38px); letter-spacing:-1.1px; line-height:1.2; margin:9px 0 9px; font-weight:750; }\n.introducao p { margin:0; color:var(--secundario); max-width:660px; }\n.abas { display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); gap:9px; margin:0 0 33px; }\n.aba { min-width:0; text-align:left; display:flex; flex-direction:column; justify-content:center; gap:2px; padding:13px 15px; border-radius:10px; border:1px solid var(--linha); color:var(--texto); background:white; min-height:70px; transition:border-color .12s,background .12s; }\n.aba small { color:var(--secundario); font-size:11px; line-height:1.25; }\n.aba strong { font-size:14px; font-weight:680; line-height:1.2; }\n.aba:hover { border-color:#a5bde7; background:#f9fbff; }\n.aba.ativa { border-color:var(--azul); background:var(--azul-claro); box-shadow:inset 0 3px var(--azul); }\n.aba.ativa strong { color:var(--azul-forte); }\n.assunto > h2 { margin:0 0 4px; font-size:23px; letter-spacing:-.6px; line-height:1.3; }\n.descricao { margin:0 0 22px; color:var(--secundario); }\n.colunas { display:grid; grid-template-columns:minmax(0,1fr) minmax(0,.95fr); gap:19px; align-items:start; }\n.cartao { background:var(--branco); border:1px solid var(--linha); border-radius:13px; padding:26px 28px; box-shadow:0 3px 16px rgba(25,50,80,.025); }\n.cartao h3 { font-size:16px; margin:0 0 18px; font-weight:740; letter-spacing:-.2px; }\n.dados { display:flex; flex-direction:column; }\n.dados > label:not(.marcar) { font-weight:630; font-size:13px; margin:0 0 6px; }\n.dados > input, .confianca select { width:100%; border:1px solid #cdd8e7; border-radius:7px; padding:11px 13px; height:44px; color:var(--texto); background:white; outline:none; margin:0 0 17px; }\n.dados > input::placeholder { color:#97a3b2; }\n.dados > input:focus, .confianca select:focus { border-color:var(--azul); box-shadow:0 0 0 3px rgba(33,87,175,.11); }\n.dados > input:disabled { background:#f4f6fa; color:var(--secundario); }\n.confianca { display:flex; align-items:start; gap:12px; }\n.confianca select { flex:1; min-width:0; }\n.confianca output { flex:0 0 auto; margin-top:4px; padding:7px 11px; color:var(--azul-forte); background:var(--azul-claro); border-radius:7px; font-weight:700; font-size:12px; }\n.marcar { display:flex; align-items:center; gap:9px; margin:-4px 0 18px; color:var(--texto); font-size:13px; cursor:pointer; }\n.marcar input { width:17px; height:17px; accent-color:var(--azul); }\n.dado-automatico { display:flex; align-items:center; justify-content:space-between; gap:12px; background:#f4f7fc; border:1px solid #e5eaf4; border-radius:7px; padding:11px 13px; margin:0 0 17px; font-size:13px; color:var(--secundario); }\n.dado-automatico output { color:var(--azul-forte); font-weight:740; text-align:right; }\n.opcional { color:var(--secundario); font-weight:400; }\n.acoes { display:flex; gap:10px; margin-top:6px; }\n.acoes button { border-radius:8px; border:1px solid var(--linha); height:44px; padding:0 22px; font-weight:700; }\n.primario { color:white; background:var(--azul); border-color:var(--azul) !important; }\n.primario:hover { background:var(--azul-forte); }\n.limpar { background:white; color:var(--secundario); }\n.limpar:hover { border-color:#93a8c9; color:var(--texto); }\n.erro { background:#fff1ef; border:1px solid #efbeb8; border-radius:8px; color:#9b3127; padding:10px 12px; margin-bottom:10px; font-size:13px; }\n.formula .expressao { display:block; color:var(--azul-forte); background:#f2f6fc; border:1px solid #e0e9f8; border-radius:8px; font-family:\"Cambria Math\",Georgia,serif; font-size:clamp(18px,2.2vw,24px); text-align:center; padding:17px 10px; margin:12px 0; overflow-wrap:anywhere; }\n.formula dl { display:grid; grid-template-columns:65px 1fr; gap:8px 14px; font-size:13px; margin:23px 0 0; }\n.formula dt { color:var(--azul-forte); font-weight:740; }\n.formula dd { margin:0; color:var(--secundario); }\n.nota-formula { color:var(--secundario); font-size:13px; margin:19px 0 0; }\n.resultado { border:1px solid #bfceea; border-radius:13px; background:white; padding:27px 28px; margin-top:19px; margin-bottom:20px; box-shadow:0 3px 16px rgba(25,50,80,.025); }\n.resposta-superior { font-size:11px; letter-spacing:1.3px; font-weight:800; color:var(--azul); }\n.numero-resposta { display:block; color:var(--azul-forte); font-size:clamp(30px,4.3vw,43px); letter-spacing:-1.1px; line-height:1.25; padding:8px 0 3px; overflow-wrap:anywhere; }\n.frase-resposta { margin:5px 0 18px; max-width:760px; color:#3a4a60; }\n.extras { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:0 24px; border-top:1px solid var(--linha); margin:13px 0 12px; padding-top:8px; }\n.extra-linha { display:flex; gap:12px; align-items:center; justify-content:space-between; border-bottom:1px solid #eef2f7; padding:9px 0; font-size:13px; }\n.extra-linha span { color:var(--secundario); }\n.extra-linha strong { color:var(--texto); text-align:right; }\n.aviso { background:var(--azul-claro); color:var(--azul-forte); padding:12px 14px; border-radius:7px; font-size:13px; margin:18px 0; }\n.passos { border-top:1px solid var(--linha); margin:20px 0 0; padding-top:12px; }\n.passos summary { color:var(--azul-forte); font-weight:700; cursor:pointer; padding:5px 0; }\n.passos summary:hover { text-decoration:underline; }\n.passos ol { margin:14px 0 0; padding:0 0 0 24px; }\n.passos li { padding:4px 0 13px 8px; }\n.passos li::marker { color:var(--azul); font-weight:700; }\n.passos li strong { font-size:14px; }\n.passos li p { font-size:13px; color:var(--secundario); margin:4px 0 0; overflow-wrap:anywhere; }\n.rodape { display:flex; justify-content:space-between; gap:14px; border-top:1px solid var(--linha); padding:24px 0 30px; margin-top:58px; color:var(--secundario); font-size:12px; }\n:focus-visible { outline:3px solid #79a8f4; outline-offset:2px; }\n@media (max-width: 860px) {\n  .colunas { grid-template-columns:1fr; }\n  .abas { gap:7px; }\n  .aba { padding:11px 9px; min-height:72px; }\n  .aba strong { font-size:13px; }\n}\n@media (max-width: 620px) {\n  .largura { width:min(100% - 28px,500px); }\n  .topo { min-height:63px; }\n  .marca { font-size:17px; }\n  .marca-extra { display:none; }\n  .introducao { padding:28px 0 19px; }\n  .introducao p { font-size:14px; }\n  .abas { grid-template-columns:repeat(2,minmax(0,1fr)); gap:7px; margin-bottom:25px; }\n  .aba { min-height:59px; padding:10px 13px; }\n  .aba:last-child { grid-column:1 / -1; min-height:52px; }\n  .assunto > h2 { font-size:21px; }\n  .descricao { font-size:14px; margin-bottom:17px; }\n  .cartao { padding:21px 18px; }\n  .colunas { gap:12px; }\n  .resultado { padding:22px 18px; margin-top:13px; }\n  .extras { grid-template-columns:1fr; }\n  .rodape { margin-top:40px; flex-direction:column; gap:5px; }\n}\n@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior:auto !important; transition:none !important; } }\n","/src/calculos.js":"/*\n * CONTAS ESTATÍSTICAS — edite aqui se uma fórmula estiver errada.\n * Não depende do navegador: podemos testar este arquivo sozinho.\n * O resultado guarda números sem arredondar. A tela arredonda só ao exibir.\n */\n(function (global) {\n  'use strict';\n\n  // Tabela Z usada nos PDFs da professora.\n  const TABELA_Z = Object.freeze({90: 1.645, 95: 1.96, 99: 2.575});\n\n  // Aceita 1,25 (decimal), 1.250 (milhar) e 1.250,50.\n  // Números inválidos, infinitos e campos vazios geram mensagens legíveis.\n  function numero(texto, nome = 'Valor') {\n    if (typeof texto === 'number') {\n      if (Number.isFinite(texto)) return texto;\n      throw new Error(`${nome}: informe um número válido.`);\n    }\n    const original = String(texto ?? '').trim().replace(/\\s/g, '');\n    if (!original) throw new Error(`${nome}: preencha este campo.`);\n    let ajustado = original;\n    if (/^[+-]?\\d{1,3}(?:\\.\\d{3})+,(?:\\d+)$/.test(original)) {\n      ajustado = original.replace(/\\./g, '').replace(',', '.');\n    } else if (/^[+-]?[1-9]\\d{0,2}(?:\\.\\d{3})+$/.test(original)) {\n      ajustado = original.replace(/\\./g, '');\n    } else if (/^[+-]?(?:\\d+(?:[.,]\\d+)?|[.,]\\d+)$/.test(original)) {\n      ajustado = original.replace(',', '.');\n    } else {\n      throw new Error(`${nome}: digite apenas um número (por exemplo, 1,25).`);\n    }\n    const resultado = Number(ajustado);\n    if (!Number.isFinite(resultado)) throw new Error(`${nome}: número grande demais.`);\n    return resultado;\n  }\n\n  function validarMaior(valor, nome, limite = 0) {\n    if (valor <= limite) throw new Error(`${nome}: deve ser maior que ${limite}.`);\n    return valor;\n  }\n  function inteiro(valor, nome, permiteZero = false) {\n    if (!Number.isSafeInteger(valor) || valor < (permiteZero ? 0 : 1)) {\n      throw new Error(`${nome}: digite um número inteiro ${permiteZero ? 'a partir de zero' : 'maior que zero'}.`);\n    }\n    return valor;\n  }\n  function porcentagem(valor, nome, permiteZero = false) {\n    if (valor < (permiteZero ? 0 : Number.MIN_VALUE) || valor >= 100) {\n      throw new Error(`${nome}: informe uma porcentagem ${permiteZero ? 'de 0 a menos de 100' : 'maior que 0 e menor que 100'}.`);\n    }\n    return valor / 100;\n  }\n  function valorCritico(confianca) {\n    if (!Object.prototype.hasOwnProperty.call(TABELA_Z, confianca)) {\n      throw new Error('Grau de confiança: escolha 90%, 95% ou 99%.');\n    }\n    return TABELA_Z[confianca];\n  }\n  // Amostras devem ser arredondadas para cima. O ajuste só evita\n  // erros minúsculos de representação binária: 600,0000000000001 -> 600.\n  function amostraInteira(valor) {\n    if (!Number.isFinite(valor) || valor > Number.MAX_SAFE_INTEGER) {\n      throw new Error('Amostra calculada grande demais. Revise a margem de erro.');\n    }\n    return Math.max(1, Math.ceil(valor - 1e-10));\n  }\n\n  // FUNCIONAMENTO DA FÓRMULA: TAMANHO DA AMOSTRA PARA A MÉDIA\n  // n = (Z × desvio-padrão / erro máximo)².\n  function amostraMedia({confianca = 95, desvio, erro}) {\n    const z = valorCritico(confianca);\n    validarMaior(desvio, 'Desvio-padrão');\n    validarMaior(erro, 'Erro máximo');\n    const exato = (z * desvio / erro) ** 2;\n    return {z, desvio, erro, exato, n: amostraInteira(exato)};\n  }\n\n  // FUNCIONAMENTO DA FÓRMULA: TAMANHO DA AMOSTRA PARA A PROPORÇÃO\n  // p e Ep são percentuais na tela, convertidos para decimal antes da conta.\n  function amostraProporcao({confianca = 95, percentual, erro}) {\n    const z = valorCritico(confianca);\n    const p = porcentagem(percentual, 'Proporção estimada');\n    const ep = porcentagem(erro, 'Erro da proporção');\n    const q = 1 - p;\n    const exato = z ** 2 * p * q / ep ** 2;\n    return {z, p, q, ep, exato, n: amostraInteira(exato)};\n  }\n\n  // FUNCIONAMENTO DA FÓRMULA: INTERVALO DE CONFIANÇA DA MÉDIA\n  // Em = Z × σ / √n. Depois subtraímos e somamos Em à média.\n  function intervaloMedia({confianca = 95, media, desvio, n}) {\n    const z = valorCritico(confianca);\n    if (desvio < 0) throw new Error('Desvio-padrão: não pode ser negativo.');\n    inteiro(n, 'Tamanho da amostra');\n    const margem = z * desvio / Math.sqrt(n);\n    const inferior = media - margem, superior = media + margem;\n    if (![inferior, superior].every(Number.isFinite)) throw new Error('Resultado grande demais. Revise os dados.');\n    return {z, media, desvio, n, margem, inferior, superior, amplitude: superior - inferior, aviso: n <= 30 ? 'Se o desvio é amostral e n é pequeno, pode ser necessário usar t de Student. Esta calculadora segue o método Z da aula.' : ''};\n  }\n\n  // FUNCIONAMENTO DA FÓRMULA: INTERVALO DE CONFIANÇA DA PROPORÇÃO\n  // p = pessoas com a característica / pessoas pesquisadas.\n  // Ep = Z × raiz[p(1-p)/n]. Não alteramos os limites artificialmente.\n  function intervaloProporcao({confianca = 95, sucessos, n, padrao = null}) {\n    const z = valorCritico(confianca);\n    inteiro(n, 'Tamanho da amostra');\n    inteiro(sucessos, 'Quantidade com a característica', true);\n    if (sucessos > n) throw new Error('Quantidade com a característica: não pode ultrapassar o total pesquisado.');\n    const p = sucessos / n, q = 1 - p;\n    const margem = z * Math.sqrt(p * q / n);\n    const inferior = p - margem, superior = p + margem;\n    const avisos = [];\n    if (sucessos < 5 || n - sucessos < 5) avisos.push('Poucos casos em um dos grupos: este método de aproximação pode não ser adequado.');\n    if (inferior < 0 || superior > 1) avisos.push('A fórmula produziu um limite fora de 0% a 100%. Confira a adequação do método.');\n    if (padrao !== null && (padrao < 0 || padrao > 100)) throw new Error('Padrão aceitável: use uma porcentagem entre 0 e 100.');\n    return {z, n, sucessos, p, q, margem, inferior, superior, padrao, avisos,\n      atendePadrao: padrao === null ? null : superior * 100 < padrao};\n  }\n\n  // FUNCIONAMENTO DA FÓRMULA: DIMINUIR O ERRO\n  // Se o erro vai ser dividido por k, a amostra cresce cerca de k² vezes.\n  function diminuirErro({confianca = 95, desvio, n, fator}) {\n    const z = valorCritico(confianca);\n    validarMaior(desvio, 'Desvio-padrão');\n    inteiro(n, 'Tamanho atual da amostra');\n    validarMaior(fator, 'Dividir o erro por', 1);\n    const erroAtual = z * desvio / Math.sqrt(n);\n    const novoErro = erroAtual / fator;\n    const exato = (z * desvio / novoErro) ** 2;\n    const novoN = amostraInteira(exato);\n    return {z, desvio, n, fator, erroAtual, novoErro, exato, novoN, adicionar: novoN - n};\n  }\n\n  global.Calculos = Object.freeze({numero, inteiro, porcentagem, valorCritico,\n    amostraInteira, amostraMedia, amostraProporcao, intervaloMedia,\n    intervaloProporcao, diminuirErro});\n})(globalThis);\n","/src/app.js":"/*\n * INTERFACE — botões, campos e apresentação dos resultados.\n * As fórmulas ficam em calculos.js; aqui só lemos entradas e mostramos a conta.\n * Para trocar o nome de um campo, altere seu <label> no index.html.\n */\n(() => {\n  'use strict';\n  const M = globalThis.Calculos;\n  const $ = id => document.getElementById(id);\n  const fmt = (n, casas = 4) => n.toLocaleString('pt-BR', {maximumFractionDigits: casas});\n  const percentual = (p, casas = 2) => `${fmt(p * 100, casas)}%`;\n  const lido = (form, nome, titulo) => M.numero(form.elements.namedItem(nome).value, titulo);\n  const confianca = form => Number(form.elements.namedItem('confianca').value);\n\n  // Trocar assunto não apaga o que foi digitado nas outras abas.\n  function abrirAba(id) {\n    for (const secao of document.querySelectorAll('.assunto')) {\n      const selecionada = secao.id === `aba-${id}`;\n      secao.hidden = !selecionada;\n      secao.classList.toggle('visivel', selecionada);\n    }\n    for (const botao of document.querySelectorAll('.aba')) {\n      const selecionado = botao.dataset.aba === id;\n      botao.classList.toggle('ativa', selecionado);\n      if (selecionado) botao.setAttribute('aria-current', 'page');\n      else botao.removeAttribute('aria-current');\n    }\n  }\n\n  // Exibe o valor Z sem pedir ao estudante que procure uma tabela.\n  function atualizarZ(form) {\n    const id = form.id.slice(5);\n    const saída = document.querySelector(`[data-z=\"${id}\"]`);\n    saída.textContent = `Z = ${fmt(M.valorCritico(confianca(form)), 3)}`;\n  }\n\n  // Campos descobertos automaticamente: o estudante não consegue editá-los.\n  function atualizarComplemento() {\n    const form = $('form-ap');\n    const desconhecida = $('ap-desconhecida').checked;\n    const campo = $('ap-p');\n    campo.disabled = desconhecida;\n    campo.placeholder = desconhecida ? '50' : 'Digite a porcentagem';\n    if (desconhecida) { $('ap-complemento').textContent = '50%'; return; }\n    try {\n      const p = M.porcentagem(M.numero(campo.value), 'Proporção');\n      $('ap-complemento').textContent = percentual(1 - p);\n    } catch (_) { $('ap-complemento').textContent = '—'; }\n  }\n  function atualizarProporcao() {\n    try {\n      const form = $('form-ip');\n      const n = M.inteiro(lido(form, 'n', 'Tamanho da amostra'), 'Tamanho da amostra');\n      const k = M.inteiro(lido(form, 'sucessos', 'Quantidade com a característica'), 'Quantidade com a característica', true);\n      $('ip-proporcao').textContent = k <= n ? `${percentual(k / n)} com a característica` : '—';\n    } catch (_) { $('ip-proporcao').textContent = '—'; }\n  }\n  function atualizarErro() {\n    try {\n      const form = $('form-de');\n      const desvio = lido(form, 'desvio', 'Desvio-padrão');\n      const n = M.inteiro(lido(form, 'n', 'Tamanho atual da amostra'), 'Tamanho atual da amostra');\n      const e = M.valorCritico(confianca(form)) * desvio / Math.sqrt(n);\n      $('de-atual').textContent = desvio > 0 ? fmt(e, 6) : '—';\n    } catch (_) { $('de-atual').textContent = '—'; }\n  }\n\n  // Cada operação usa EXCLUSIVAMENTE as funções matemáticas do arquivo calculos.js.\n  function executar(id, form) {\n    const z = M.valorCritico(confianca(form));\n    if (id === 'am') {\n      const r = M.amostraMedia({confianca: confianca(form), desvio: lido(form, 'desvio', 'Desvio-padrão'), erro: lido(form, 'erro', 'Erro máximo')});\n      return {\n        titulo: 'Tamanho mínimo da amostra', valor: `n = ${fmt(r.n, 0)}`,\n        frase: `São necessárias pelo menos ${fmt(r.n, 0)} observações para estimar a média com ${confianca(form)}% de confiança.`,\n        extras: [['Antes de arredondar', fmt(r.exato, 6)]],\n        passos: [\n          ['Identificar o valor crítico', `Para ${confianca(form)}% de confiança, usamos Z = ${fmt(z, 3)}.`],\n          ['Substituir na fórmula', `n = (${fmt(z, 3)} × ${fmt(r.desvio)} ÷ ${fmt(r.erro)})² = ${fmt(r.exato, 6)}.`],\n          ['Arredondar para cima', `Precisamos de ${fmt(r.n, 0)} observações, pois não existe uma fração de pessoa ou medição.`]\n        ]\n      };\n    }\n    if (id === 'ap') {\n      const p = $('ap-desconhecida').checked ? 50 : lido(form, 'p', 'Proporção estimada');\n      const r = M.amostraProporcao({confianca: confianca(form), percentual: p, erro: lido(form, 'erro', 'Erro da proporção')});\n      return {\n        titulo: 'Tamanho mínimo da amostra', valor: `n = ${fmt(r.n, 0)}`,\n        frase: `São necessárias pelo menos ${fmt(r.n, 0)} observações para estimar a proporção com ${confianca(form)}% de confiança.`,\n        extras: [['Proporção (p)', percentual(r.p)], ['Complemento (1 − p)', percentual(r.q)], ['Antes de arredondar', fmt(r.exato, 6)]],\n        passos: [\n          ['Transformar porcentagens em decimais', `p = ${fmt(r.p, 4)}, complemento = ${fmt(r.q, 4)} e Ep = ${fmt(r.ep, 4)}.`],\n          ['Aplicar a fórmula', `n = ${fmt(z, 3)}² × ${fmt(r.p, 4)} × ${fmt(r.q, 4)} ÷ ${fmt(r.ep, 4)}² = ${fmt(r.exato, 6)}.`],\n          ['Arredondar para cima', `A amostra mínima é de ${fmt(r.n, 0)} observações.`]\n        ]\n      };\n    }\n    if (id === 'im') {\n      const r = M.intervaloMedia({confianca: confianca(form), media: lido(form, 'media', 'Média amostral'), desvio: lido(form, 'desvio', 'Desvio-padrão'), n: lido(form, 'n', 'Tamanho da amostra')});\n      return {\n        titulo: 'Intervalo de confiança', valor: `${fmt(r.inferior, 4)} a ${fmt(r.superior, 4)}`,\n        frase: `Com ${confianca(form)}% de confiança, estimamos a média populacional entre ${fmt(r.inferior, 4)} e ${fmt(r.superior, 4)}.`,\n        extras: [['Margem de erro (Em)', fmt(r.margem, 6)], ['Limite inferior', fmt(r.inferior, 6)], ['Limite superior', fmt(r.superior, 6)]],\n        aviso: r.aviso,\n        passos: [\n          ['Escolher o valor crítico', `Para ${confianca(form)}% de confiança, usamos Z = ${fmt(z, 3)}.`],\n          ['Calcular a margem de erro', `Em = ${fmt(z, 3)} × ${fmt(r.desvio)} ÷ √${fmt(r.n, 0)} = ${fmt(r.margem, 6)}.`],\n          ['Encontrar os dois limites', `${fmt(r.media)} − ${fmt(r.margem, 6)} = ${fmt(r.inferior, 6)}; ${fmt(r.media)} + ${fmt(r.margem, 6)} = ${fmt(r.superior, 6)}.`]\n        ]\n      };\n    }\n    if (id === 'ip') {\n      const padraoTexto = form.elements.namedItem('padrao').value.trim();\n      const r = M.intervaloProporcao({confianca: confianca(form), sucessos: lido(form, 'sucessos', 'Quantidade com a característica'), n: lido(form, 'n', 'Tamanho da amostra'), padrao: padraoTexto ? lido(form, 'padrao', 'Padrão aceitável') : null});\n      let comparacao = '';\n      if (r.padrao !== null) comparacao = r.atendePadrao\n        ? `O limite superior está abaixo do padrão de ${fmt(r.padrao)}%. Pelo critério informado, a condição foi atendida.`\n        : `O intervalo não fica inteiro abaixo do padrão de ${fmt(r.padrao)}%. Não dá para garantir a condição.`;\n      return {\n        titulo: 'Intervalo de confiança', valor: `${percentual(r.inferior)} a ${percentual(r.superior)}`,\n        frase: `Com ${confianca(form)}% de confiança, estimamos a proporção populacional entre ${percentual(r.inferior)} e ${percentual(r.superior)}.`,\n        extras: [['Com a característica', percentual(r.p)], ['Sem a característica', percentual(r.q)], ['Margem de erro', `${fmt(r.margem * 100, 4)} pontos percentuais`]],\n        aviso: [...r.avisos, comparacao].filter(Boolean).join(' '),\n        passos: [\n          ['Encontrar a proporção', `p = ${fmt(r.sucessos, 0)} ÷ ${fmt(r.n, 0)} = ${fmt(r.p, 6)}; complemento = ${fmt(r.q, 6)}.`],\n          ['Calcular a margem de erro', `Ep = ${fmt(z, 3)} × √(${fmt(r.p, 6)} × ${fmt(r.q, 6)} ÷ ${fmt(r.n, 0)}) = ${fmt(r.margem, 6)}.`],\n          ['Encontrar os limites', `Subtraímos e somamos a margem à proporção: ${percentual(r.inferior)} a ${percentual(r.superior)}.`]\n        ]\n      };\n    }\n    if (id === 'de') {\n      const r = M.diminuirErro({confianca: confianca(form), desvio: lido(form, 'desvio', 'Desvio-padrão'), n: lido(form, 'n', 'Tamanho atual da amostra'), fator: lido(form, 'k', 'Dividir o erro por')});\n      return {\n        titulo: 'Novo tamanho da amostra', valor: `n = ${fmt(r.novoN, 0)}`,\n        frase: `Para dividir o erro por ${fmt(r.fator)} é preciso aumentar a amostra em ${fmt(r.adicionar, 0)} observações.`,\n        extras: [['Amostra atual', fmt(r.n, 0)], ['Erro atual', fmt(r.erroAtual, 6)], ['Novo erro', fmt(r.novoErro, 6)], ['Observações adicionais', fmt(r.adicionar, 0)]],\n        passos: [\n          ['Calcular o erro atual', `Em = ${fmt(z, 3)} × ${fmt(r.desvio)} ÷ √${fmt(r.n, 0)} = ${fmt(r.erroAtual, 6)}.`],\n          ['Diminuir o erro', `Novo Em = ${fmt(r.erroAtual, 6)} ÷ ${fmt(r.fator)} = ${fmt(r.novoErro, 6)}.`],\n          ['Recalcular a amostra', `Novo n = (${fmt(z, 3)} × ${fmt(r.desvio)} ÷ ${fmt(r.novoErro, 6)})² ≈ ${fmt(r.exato, 4)}. Arredondamos para ${fmt(r.novoN, 0)}.`]\n        ]\n      };\n    }\n    throw new Error('Cálculo não encontrado.');\n  }\n\n  // Cria o resultado usando apenas textContent: entradas não viram HTML.\n  function colocarTexto(elemento, classe, texto) {\n    const filho = document.createElement(elemento);\n    filho.className = classe;\n    filho.textContent = texto;\n    return filho;\n  }\n  function mostrarResultado(secao, resposta) {\n    const painel = secao.querySelector('.resultado');\n    painel.replaceChildren();\n    const resumo = colocarTexto('div', 'resposta-superior', 'RESPOSTA DO EXERCÍCIO');\n    const valor = colocarTexto('strong', 'numero-resposta', resposta.valor);\n    const frase = colocarTexto('p', 'frase-resposta', resposta.frase);\n    painel.append(resumo, valor, frase);\n\n    if (resposta.extras?.length) {\n      const tabela = colocarTexto('div', 'extras', '');\n      for (const [nome, dado] of resposta.extras) {\n        const linha = colocarTexto('div', 'extra-linha', '');\n        linha.append(colocarTexto('span', '', nome), colocarTexto('strong', '', dado));\n        tabela.append(linha);\n      }\n      painel.append(tabela);\n    }\n    if (resposta.aviso) painel.append(colocarTexto('p', 'aviso', resposta.aviso));\n    const detalhes = document.createElement('details');\n    detalhes.className = 'passos';\n    const titulo = document.createElement('summary');\n    titulo.textContent = 'Ver resolução passo a passo';\n    detalhes.append(titulo);\n    const lista = document.createElement('ol');\n    resposta.passos.forEach(([nome, explicacao]) => {\n      const passo = document.createElement('li');\n      passo.append(colocarTexto('strong', '', nome), colocarTexto('p', '', explicacao));\n      lista.append(passo);\n    });\n    detalhes.append(lista);\n    painel.append(detalhes);\n    painel.hidden = false;\n  }\n\n  // A entrada mudou: esconde o resultado anterior para não confundir cálculos.\n  for (const form of document.querySelectorAll('form.dados')) {\n    const secao = form.closest('.assunto');\n    const aviso = form.querySelector('.erro');\n    const resultado = secao.querySelector('.resultado');\n    form.addEventListener('submit', evento => {\n      evento.preventDefault();\n      aviso.hidden = true;\n      resultado.hidden = true;\n      try { mostrarResultado(secao, executar(form.id.slice(5), form)); }\n      catch (erro) {\n        aviso.textContent = erro instanceof Error ? erro.message : 'Não foi possível calcular. Revise os valores.';\n        aviso.hidden = false;\n      }\n    });\n    form.addEventListener('input', () => {\n      resultado.hidden = true;\n      aviso.hidden = true;\n      atualizarComplemento(); atualizarProporcao(); atualizarErro();\n    });\n    form.addEventListener('change', () => {\n      resultado.hidden = true;\n      aviso.hidden = true;\n      atualizarZ(form); atualizarComplemento(); atualizarProporcao(); atualizarErro();\n    });\n    form.addEventListener('reset', () => {\n      resultado.hidden = true;\n      aviso.hidden = true;\n      // Os valores só voltam ao padrão após o evento reset terminar.\n      queueMicrotask(() => { atualizarZ(form); atualizarComplemento(); atualizarProporcao(); atualizarErro(); });\n    });\n    atualizarZ(form);\n  }\n  document.querySelectorAll('[data-aba]').forEach(botao => {\n    botao.addEventListener('click', () => abrirAba(botao.dataset.aba));\n  });\n  atualizarComplemento(); atualizarProporcao(); atualizarErro(); abrirAba('am');\n})();\n","/":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"theme-color\" content=\"#174CA0\">\n  <meta name=\"description\" content=\"Calcule tamanho da amostra e intervalos de confiança, com explicações simples e claras.\">\n  <title>Estatística Aplicada — Calculadora</title>\n  <link rel=\"stylesheet\" href=\"./assets/style.css\">\n  <script src=\"./src/calculos.js\" defer></script>\n  <script src=\"./src/app.js\" defer></script>\n</head>\n<body>\n  <header class=\"cabecalho\">\n    <div class=\"largura topo\">\n      <a class=\"marca\" href=\"./\" aria-label=\"Estatística Aplicada — início\">\n        <span class=\"marca-sinal\" aria-hidden=\"true\">Σ</span>\n        <span>Estatística <strong>Aplicada</strong></span>\n      </a>\n      <span class=\"marca-extra\">Calculadora da disciplina</span>\n    </div>\n  </header>\n\n  <main class=\"largura\">\n    <div class=\"introducao\">\n      <span class=\"sobretitulo\">FÓRMULAS DA AULA</span>\n      <h1>Qual cálculo você precisa fazer?</h1>\n      <p>Escolha o assunto, preencha os valores do exercício e veja como chegar à resposta.</p>\n    </div>\n\n    <!-- As cinco abas são os cinco assuntos do index.html de referência. -->\n    <nav class=\"abas\" aria-label=\"Escolher cálculo\">\n      <button type=\"button\" class=\"aba ativa\" data-aba=\"am\" aria-current=\"page\"><small>Tamanho da amostra</small><strong>Média</strong></button>\n      <button type=\"button\" class=\"aba\" data-aba=\"ap\"><small>Tamanho da amostra</small><strong>Proporção</strong></button>\n      <button type=\"button\" class=\"aba\" data-aba=\"im\"><small>Intervalo de confiança</small><strong>Média</strong></button>\n      <button type=\"button\" class=\"aba\" data-aba=\"ip\"><small>Intervalo de confiança</small><strong>Proporção</strong></button>\n      <button type=\"button\" class=\"aba\" data-aba=\"de\"><small>Ajuste da amostra</small><strong>Diminuir o erro</strong></button>\n    </nav>\n\n    <!-- Assunto 1: calcular quantas observações são necessárias para a média. -->\n    <section class=\"assunto visivel\" id=\"aba-am\" aria-labelledby=\"titulo-am\">\n      <h2 id=\"titulo-am\">Tamanho da amostra para a média</h2>\n      <p class=\"descricao\">Quantas observações preciso para estimar uma média com a precisão desejada?</p>\n      <div class=\"colunas\">\n        <form class=\"cartao dados\" id=\"form-am\" novalidate>\n          <h3>Dados do exercício</h3>\n          <label for=\"am-confianca\">Grau de confiança</label>\n          <div class=\"confianca\"><select id=\"am-confianca\" name=\"confianca\"><option value=\"90\">90%</option><option value=\"95\" selected>95%</option><option value=\"99\">99%</option></select><output data-z=\"am\">Z = 1,96</output></div>\n          <label for=\"am-desvio\">Desvio-padrão populacional (σ)</label>\n          <input id=\"am-desvio\" name=\"desvio\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite o desvio-padrão\">\n          <label for=\"am-erro\">Erro amostral máximo aceito (Em)</label>\n          <input id=\"am-erro\" name=\"erro\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite a margem de erro\">\n          <div class=\"erro\" role=\"alert\" hidden></div>\n          <div class=\"acoes\"><button class=\"primario\" type=\"submit\">Calcular</button><button class=\"limpar\" type=\"reset\">Limpar</button></div>\n        </form>\n        <aside class=\"cartao formula\"><h3>Fórmula utilizada</h3><div class=\"expressao\">n = (Z · σ / Em)²</div><dl><dt>n</dt><dd>Tamanho mínimo da amostra</dd><dt>σ</dt><dd>Desvio-padrão populacional</dd><dt>Em</dt><dd>Erro máximo aceito</dd><dt>Z</dt><dd>Valor relacionado à confiança</dd></dl></aside>\n      </div>\n      <div class=\"resultado\" hidden></div>\n    </section>\n\n    <!-- Assunto 2: amostra necessária para estimar uma porcentagem. -->\n    <section class=\"assunto\" id=\"aba-ap\" aria-labelledby=\"titulo-ap\" hidden>\n      <h2 id=\"titulo-ap\">Tamanho da amostra para a proporção</h2>\n      <p class=\"descricao\">Quantas pessoas ou observações preciso para estimar uma porcentagem?</p>\n      <div class=\"colunas\">\n        <form class=\"cartao dados\" id=\"form-ap\" novalidate>\n          <h3>Dados do exercício</h3>\n          <label for=\"ap-confianca\">Grau de confiança</label>\n          <div class=\"confianca\"><select id=\"ap-confianca\" name=\"confianca\"><option value=\"90\">90%</option><option value=\"95\" selected>95%</option><option value=\"99\">99%</option></select><output data-z=\"ap\">Z = 1,96</output></div>\n          <label for=\"ap-p\">Proporção estimada (p), em %</label>\n          <input id=\"ap-p\" name=\"p\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite a porcentagem\">\n          <label class=\"marcar\"><input type=\"checkbox\" name=\"desconhecida\" id=\"ap-desconhecida\"> Proporção desconhecida (usar 50%)</label>\n          <div class=\"dado-automatico\"><span>Complemento (1 − p)</span><output id=\"ap-complemento\">—</output></div>\n          <label for=\"ap-erro\">Erro da proporção (Ep), em %</label>\n          <input id=\"ap-erro\" name=\"erro\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite o erro em %\">\n          <div class=\"erro\" role=\"alert\" hidden></div>\n          <div class=\"acoes\"><button class=\"primario\" type=\"submit\">Calcular</button><button class=\"limpar\" type=\"reset\">Limpar</button></div>\n        </form>\n        <aside class=\"cartao formula\"><h3>Fórmula utilizada</h3><div class=\"expressao\">n = Z² · p · (1 − p) / Ep²</div><dl><dt>p</dt><dd>Proporção estimada</dd><dt>1 − p</dt><dd>Complemento da proporção</dd><dt>Ep</dt><dd>Erro da proporção, em decimal</dd><dt>Z</dt><dd>Valor relacionado à confiança</dd></dl></aside>\n      </div>\n      <div class=\"resultado\" hidden></div>\n    </section>\n\n    <!-- Assunto 3: intervalo entre dois valores para a média. -->\n    <section class=\"assunto\" id=\"aba-im\" aria-labelledby=\"titulo-im\" hidden>\n      <h2 id=\"titulo-im\">Intervalo de confiança para a média</h2>\n      <p class=\"descricao\">Entre quais valores pode estar a média verdadeira da população?</p>\n      <div class=\"colunas\">\n        <form class=\"cartao dados\" id=\"form-im\" novalidate>\n          <h3>Dados do exercício</h3>\n          <label for=\"im-confianca\">Grau de confiança</label>\n          <div class=\"confianca\"><select id=\"im-confianca\" name=\"confianca\"><option value=\"90\">90%</option><option value=\"95\" selected>95%</option><option value=\"99\">99%</option></select><output data-z=\"im\">Z = 1,96</output></div>\n          <label for=\"im-media\">Média amostral (x̄)</label><input id=\"im-media\" name=\"media\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite a média\">\n          <label for=\"im-desvio\">Desvio-padrão (σ ou s)</label><input id=\"im-desvio\" name=\"desvio\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite o desvio-padrão\">\n          <label for=\"im-n\">Tamanho da amostra (n)</label><input id=\"im-n\" name=\"n\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"Digite a quantidade\">\n          <div class=\"erro\" role=\"alert\" hidden></div>\n          <div class=\"acoes\"><button class=\"primario\" type=\"submit\">Calcular</button><button class=\"limpar\" type=\"reset\">Limpar</button></div>\n        </form>\n        <aside class=\"cartao formula\"><h3>Fórmulas utilizadas</h3><div class=\"expressao\">Em = Z · σ / √n</div><div class=\"expressao\">IC = x̄ ± Em</div><dl><dt>x̄</dt><dd>Média da amostra</dd><dt>Em</dt><dd>Margem de erro calculada</dd><dt>n</dt><dd>Quantidade de observações</dd></dl></aside>\n      </div>\n      <div class=\"resultado\" hidden></div>\n    </section>\n\n    <!-- Assunto 4: intervalo entre duas porcentagens. -->\n    <section class=\"assunto\" id=\"aba-ip\" aria-labelledby=\"titulo-ip\" hidden>\n      <h2 id=\"titulo-ip\">Intervalo de confiança para a proporção</h2>\n      <p class=\"descricao\">Entre quais porcentagens pode estar a proporção verdadeira da população?</p>\n      <div class=\"colunas\">\n        <form class=\"cartao dados\" id=\"form-ip\" novalidate>\n          <h3>Dados do exercício</h3>\n          <label for=\"ip-confianca\">Grau de confiança</label>\n          <div class=\"confianca\"><select id=\"ip-confianca\" name=\"confianca\"><option value=\"90\">90%</option><option value=\"95\" selected>95%</option><option value=\"99\">99%</option></select><output data-z=\"ip\">Z = 1,96</output></div>\n          <label for=\"ip-sucessos\">Quantidade com a característica</label><input id=\"ip-sucessos\" name=\"sucessos\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"Digite a quantidade\">\n          <label for=\"ip-n\">Tamanho da amostra (n)</label><input id=\"ip-n\" name=\"n\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"Digite o total pesquisado\">\n          <div class=\"dado-automatico\"><span>Proporção da amostra</span><output id=\"ip-proporcao\">—</output></div>\n          <label for=\"ip-padrao\">Padrão aceitável (%) <span class=\"opcional\">— opcional</span></label><input id=\"ip-padrao\" name=\"padrao\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Somente se o exercício pedir\">\n          <div class=\"erro\" role=\"alert\" hidden></div>\n          <div class=\"acoes\"><button class=\"primario\" type=\"submit\">Calcular</button><button class=\"limpar\" type=\"reset\">Limpar</button></div>\n        </form>\n        <aside class=\"cartao formula\"><h3>Fórmulas utilizadas</h3><div class=\"expressao\">p = sucessos / n</div><div class=\"expressao\">Ep = Z · √[p(1 − p) / n]</div><div class=\"expressao\">IC = p ± Ep</div><dl><dt>p</dt><dd>Proporção da amostra</dd><dt>Ep</dt><dd>Margem de erro da proporção</dd><dt>n</dt><dd>Total pesquisado</dd></dl></aside>\n      </div>\n      <div class=\"resultado\" hidden></div>\n    </section>\n\n    <!-- Assunto 5: a amostra cresce quando exigimos erro menor. -->\n    <section class=\"assunto\" id=\"aba-de\" aria-labelledby=\"titulo-de\" hidden>\n      <h2 id=\"titulo-de\">Diminuir o erro da média</h2>\n      <p class=\"descricao\">Se eu quiser um erro menor, quantas observações adicionais serão necessárias?</p>\n      <div class=\"colunas\">\n        <form class=\"cartao dados\" id=\"form-de\" novalidate>\n          <h3>Dados do exercício</h3>\n          <label for=\"de-confianca\">Grau de confiança</label>\n          <div class=\"confianca\"><select id=\"de-confianca\" name=\"confianca\"><option value=\"90\">90%</option><option value=\"95\" selected>95%</option><option value=\"99\">99%</option></select><output data-z=\"de\">Z = 1,96</output></div>\n          <label for=\"de-desvio\">Desvio-padrão (σ ou s)</label><input id=\"de-desvio\" name=\"desvio\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite o desvio-padrão\">\n          <label for=\"de-n\">Tamanho atual da amostra (n)</label><input id=\"de-n\" name=\"n\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"Digite o tamanho atual\">\n          <div class=\"dado-automatico\"><span>Erro atual (Em)</span><output id=\"de-atual\">—</output></div>\n          <label for=\"de-k\">Dividir o erro por quantas vezes?</label><input id=\"de-k\" name=\"k\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite um valor maior que 1\">\n          <div class=\"erro\" role=\"alert\" hidden></div>\n          <div class=\"acoes\"><button class=\"primario\" type=\"submit\">Calcular</button><button class=\"limpar\" type=\"reset\">Limpar</button></div>\n        </form>\n        <aside class=\"cartao formula\"><h3>Fórmulas utilizadas</h3><div class=\"expressao\">Novo Em = Em / k</div><div class=\"expressao\">Novo n = (Z · σ / Novo Em)²</div><dl><dt>k</dt><dd>Quantas vezes o erro vai diminuir</dd><dt>Em</dt><dd>Margem de erro atual</dd><dt>n</dt><dd>Quantidade de observações</dd></dl><p class=\"nota-formula\">Ao reduzir o erro pela metade, precisamos de aproximadamente 4 vezes mais observações.</p></aside>\n      </div>\n      <div class=\"resultado\" hidden></div>\n    </section>\n\n    <footer class=\"rodape\"><span>Uma ferramenta de apoio aos exercícios de Estatística Aplicada.</span><span>RFB · 2026</span></footer>\n  </main>\n</body>\n</html>\n"};
export default { async fetch(request) {
  const caminho = new URL(request.url).pathname;
  if (caminho === '/api/saude') return Response.json({ok:true,versao:'1.0.0',modo:'estatico'});
  if (request.method !== 'GET' && request.method !== 'HEAD') return new Response('Método não permitido', {status:405,headers:{Allow:'GET, HEAD'}});
  const arquivo = FILES[caminho];
  if (arquivo === undefined) return new Response('Página não encontrada', {status:404});
  const tipo = caminho.endsWith('.css') ? 'text/css' : caminho.endsWith('.js') ? 'text/javascript' : 'text/html';
  return new Response(request.method === 'HEAD' ? null : arquivo, {status:200,headers:{'Content-Type':tipo+'; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
}};
